let file = """{"version":3,"file":"mathUtil-CwvCWDEa.js","names":[],"sources":["../../src/utils/mathUtil.ts"],"sourcesContent":["import { clamp } from 'es-toolkit/math'\n\nimport type { ReadOnlyRect } from '@/lib/litegraph/src/interfaces'\nimport type { Bounds } from '@/renderer/core/layout/types'\n\n/** A rectangle's viewport edges: the DOMRect subset, so a DOMRect is directly assignable. */\nexport type RectEdges = Pick<DOMRect, 'left' | 'top' | 'right' | 'bottom'>\n\n/**\n * Clips a rectangle to `bounds`: each edge is limited independently, so the\n * rect shrinks to the overlapping region rather than being moved to fit.\n * Keeps an interaction rectangle (the canvas selection box, the assets\n * marquee) inside its own surface. Both the rect and the bounds use\n * viewport-style edges (left/top/right/bottom), e.g. a DOMRect.\n */\nexport function clipRectToBounds(\n  rect: RectEdges,\n  bounds: RectEdges\n): RectEdges {\n  return {\n    left: clamp(rect.left, bounds.left, bounds.right),\n    top: clamp(rect.top, bounds.top, bounds.bottom),\n    right: clamp(rect.right, bounds.left, bounds.right),\n    bottom: clamp(rect.bottom, bounds.top, bounds.bottom)\n  }\n}\n\n/**\n * Linearly maps a value from [min, max] to [0, 1].\n * Returns 0 when min equals max to avoid division by zero.\n */\nexport function normalize(value: number, min: number, max: number): number {\n  return max === min ? 0 : (value - min) / (max - min)\n}\n\n/**\n * Linearly maps a normalized value from [0, 1] back to [min, max].\n */\nexport function denormalize(\n  normalized: number,\n  min: number,\n  max: number\n): number {\n  return min + normalized * (max - min)\n}\n\n/** Simple 2D point or size as [x, y] or [width, height] */\ntype Vec2 = readonly [number, number]\n\n/** `value` wrapped into `[0, length)`. Unlike `%`, negatives wrap to the end. */\nexport const wrapIndex = (value: number, length: number): number =>\n  ((value % length) + length) % length\n\n/**\n * Finds the greatest common divisor (GCD) for two numbers using iterative\n * Euclidean algorithm. Uses iteration instead of recursion to avoid stack\n * overflow with large inputs or small floating-point step values.\n *\n * For floating-point numbers, uses a tolerance-based approach to handle\n * precision issues and limits iterations to prevent hangs.\n *\n * @param a - The first number.\n * @param b - The second number.\n * @returns The GCD of the two numbers.\n */\nexport const gcd = (a: number, b: number): number => {\n  // Use absolute values to handle negative numbers\n  let x = Math.abs(a)\n  let y = Math.abs(b)\n\n  // Handle edge cases\n  if (x === 0) return y\n  if (y === 0) return x\n\n  // For floating-point numbers, use tolerance-based comparison\n  // This prevents infinite loops due to floating-point precision issues\n  const epsilon = 1e-10\n  const maxIterations = 100\n\n  let iterations = 0\n  while (y > epsilon && iterations < maxIterations) {\n    ;[x, y] = [y, x % y]\n    iterations++\n  }\n\n  return x\n}\n\n/**\n * Finds the least common multiple (LCM) for two numbers.\n *\n * @param a - The first number.\n * @param b - The second number.\n * @returns The LCM of the two numbers.\n */\nexport const lcm = (a: number, b: number): number => {\n  return Math.abs(a * b) / gcd(a, b)\n}\n\n/**\n * Computes the union (bounding box) of multiple rectangles using a single-pass algorithm.\n *\n * Finds the minimum and maximum x/y coordinates across all rectangles to create\n * a single bounding rectangle that contains all input rectangles. Optimized for\n * performance with V8-friendly tuple access patterns.\n *\n * @param rectangles - Array of rectangle tuples in [x, y, width, height] format\n * @returns Bounds object with union rectangle, or null if no rectangles provided\n */\nexport function computeUnionBounds(\n  rectangles: readonly ReadOnlyRect[]\n): Bounds | null {\n  const n = rectangles.length\n  if (n === 0) {\n    return null\n  }\n\n  const r0 = rectangles[0]\n  let minX = r0[0]\n  let minY = r0[1]\n  let maxX = minX + r0[2]\n  let maxY = minY + r0[3]\n\n  for (let i = 1; i < n; i++) {\n    const r = rectangles[i]\n    const x1 = r[0]\n    const y1 = r[1]\n    const x2 = x1 + r[2]\n    const y2 = y1 + r[3]\n\n    if (x1 < minX) minX = x1\n    if (y1 < minY) minY = y1\n    if (x2 > maxX) maxX = x2\n    if (y2 > maxY) maxY = y2\n  }\n\n  return {\n    x: minX,\n    y: minY,\n    width: maxX - minX,\n    height: maxY - minY\n  }\n}\n\n/**\n * Checks if any item with pos/size overlaps a rectangle (AABB test).\n * @param items Items with pos [x, y] and size [width, height]\n * @param rect Rectangle as [x, y, width, height]\n * @returns `true` if any item overlaps the rect\n */\nexport function anyItemOverlapsRect(\n  items: Iterable<{ pos: Vec2; size: Vec2 }>,\n  rect: ReadOnlyRect\n): boolean {\n  const rectRight = rect[0] + rect[2]\n  const rectBottom = rect[1] + rect[3]\n\n  for (const item of items) {\n    const overlaps =\n      item.pos[0] < rectRight &&\n      item.pos[0] + item.size[0] > rect[0] &&\n      item.pos[1] < rectBottom &&\n      item.pos[1] + item.size[1] > rect[1]\n\n    if (overlaps) return true\n  }\n  return false\n}\n"],"mappings":"uFAeA,SAAgB,iBACd,EACA,EACW,CACX,MAAO,CACL,KAAM,EAAM,EAAK,KAAM,EAAO,KAAM,EAAO,KAAK,EAChD,IAAK,EAAM,EAAK,IAAK,EAAO,IAAK,EAAO,MAAM,EAC9C,MAAO,EAAM,EAAK,MAAO,EAAO,KAAM,EAAO,KAAK,EAClD,OAAQ,EAAM,EAAK,OAAQ,EAAO,IAAK,EAAO,MAAM,CACtD,CACF,CAMA,SAAgB,UAAU,EAAe,EAAa,EAAqB,CACzE,OAAO,IAAQ,EAAM,GAAK,EAAQ,IAAQ,EAAM,EAClD,CAKA,SAAgB,YACd,EACA,EACA,EACQ,CACR,OAAO,EAAM,GAAc,EAAM,EACnC,CAMA,IAAa,WAAa,EAAe,KACrC,EAAQ,EAAU,GAAU,EAcnB,KAAO,EAAW,IAAsB,CAEnD,IAAI,EAAI,KAAK,IAAI,CAAC,EACd,EAAI,KAAK,IAAI,CAAC,EAGlB,GAAI,IAAM,EAAG,OAAO,EACpB,GAAI,IAAM,EAAG,OAAO,EAIpB,IAGI,EAAa,EACjB,KAAO,EAAI,OAAW,EAAa,KAChC,CAAC,EAAG,GAAK,CAAC,EAAG,EAAI,CAAC,EACnB,IAGF,OAAO,CACT,EASa,KAAO,EAAW,IACtB,KAAK,IAAI,EAAI,CAAC,EAAI,IAAI,EAAG,CAAC,EAanC,SAAgB,mBACd,EACe,CACf,IAAM,EAAI,EAAW,OACrB,GAAI,IAAM,EACR,OAAO,KAGT,IAAM,EAA